-- string.buffer: methods, serialization format and error messages.
local buffer = require("string.buffer")
local function e(...) print(pcall(...)) end
local function hex(s) return (s:gsub(".", function(c) return string.format("%02x", c:byte()) end)) end

print(type(buffer.new), getmetatable(buffer.new()), require("string.buffer") == buffer)
local b = buffer.new()
print(b:put("abc", 123, 1.5, -0.0, 1e100):put() == b, #b, b:tostring(), tostring(b))
print(b:get(2), b:get(0), b:get(3), b:get(), #b, b:get(), b:get(5))
b:put("hello world")
print(b:get(5, 1, nil), #b)
b:putf("%d-%s-%5.1f|%q", 7, "y", 2.25, "a\n")
print(b:tostring(), #b)
b:reset(); print(#b, b:tostring() == "")
b:put(setmetatable({}, {__tostring = function() return "TS" end}), buffer.new():put("BUF"))
print(b:tostring())
print(b:skip(1):tostring(), b:skip(100):tostring(), #b)
b:set("referenced"); print(b:get(3), #b, b:tostring()); b:put("!"); print(b:tostring())
b:set("abc"):skip(10); print(#b, b:tostring() == "")
print(b:free() == b, #b, b:put("again"):tostring())
print(("%s|%s"):format(buffer.new():put("x"), 1))
print(b.tostring == getmetatable(b).__tostring and "same tostring" or "different")
local x = buffer.new()
for i = 1, 10 do x:put(("y"):rep(i * 7)) end
print(#x, select(2, x:reserve(1)), select(2, x:reserve(1000)))
local p, n = x:reserve(16); print(type(p), n >= 16); x:commit(3); print(#x)
local q, m = x:ref(); print(type(q), m)
local y = buffer.new(100); print(select(2, y:reserve(0)), select(2, y:reserve(200)))
print(#buffer.new(0), #buffer.new(nil, {}), #buffer.new({}))

-- errors
e(b.put, b, {})
e(b.put, b, true)
e(b.put, b, b)
e(b.putf, b, "%s", b)
e(b.putf, b, "%d", "x")
e(b.get, b, -1)
e(b.get, b, "x")
e(b.skip, b)
e(b.commit, b, 1e6)
e(b.set, b, 123)
e(b.set, b)
e(b.reserve, b, -1)
e(b.put, nil, "x")
e(b.tostring, {})
e(function() return #setmetatable({}, getmetatable(b)) end)
e(buffer.new, -1)
e(buffer.new, "x")
e(buffer.new, 1, 2)
e(buffer.new, {dict = {1}})
e(buffer.new, {metatable = {"x"}})
e(buffer.new, {dict = {"a", false, "b"}})
e(b.putcdata, b, "x", 1)
print(pcall(function() b:put("x"):nosuch() end))

-- serialization: exact byte format
for _, v in ipairs{true, false, 0, -1, 0.5, 1e300, -1/0, "", "abc", ("x"):rep(200), ("y"):rep(8000)} do
  local s = buffer.encode(v); print(#s, hex(s:sub(1, 12)), buffer.decode(s) == v)
end
print(hex(buffer.encode(nil)), buffer.decode(buffer.encode(nil)))
print(hex(buffer.encode({})), hex(buffer.encode({1, 2, 3})), hex(buffer.encode({[0] = 0, 1})), hex(buffer.encode({nil, 2})))
print(hex(buffer.encode({x = 1})), hex(buffer.encode({1, x = true})))
local t = buffer.decode(buffer.encode({1, 2, {3, {4}}, s = "str", [true] = false, [1.5] = "f"}))
print(t[1], t[2], t[3][1], t[3][2][1], t.s, t[true], t[1.5])
local nan = buffer.decode(buffer.encode(0/0)); print(nan ~= nan)
e(buffer.encode, print)
e(buffer.encode, coroutine.create(print))
e(buffer.encode, {f = print})
e(buffer.encode)
e(buffer.decode, "")
e(buffer.decode, "\1\2")
e(buffer.decode, "\19")
e(buffer.decode, "\31")
e(buffer.decode, "\6\1\2")
e(buffer.decode, "\7\1")
e(buffer.decode, "\35ab")
e(buffer.decode, "\9\1")
e(buffer.decode, "\9\1\1\1\1")
e(buffer.decode, "\9\1\0\1")
e(buffer.decode, "\15\0")
e(buffer.decode, "\14\0")
e(buffer.decode, "\255\0\0\0")
e(buffer.decode, 123)
local deep = {}; local cur = deep; for i = 1, 150 do cur[1] = {}; cur = cur[1] end
e(buffer.encode, deep)
local deep2 = {}; cur = deep2; for i = 1, 99 do cur[1] = {}; cur = cur[1] end
print(pcall(buffer.encode, deep2))

-- dictionaries and metatables
local MT = {__index = {kind = "obj"}}
local d = buffer.new({dict = {"aa", "bb", "aa"}, metatable = {MT}})
d:encode({aa = 1, bb = 2, cc = 3}); print(#d)
local dd = d:decode(); print(dd.aa, dd.bb, dd.cc, #d)
d:encode(setmetatable({1}, MT)); print(hex(d:tostring()))
local o = d:decode(); print(getmetatable(o) == MT, o.kind, o[1])
d:encode("x"):encode(1):encode({}); print(d:decode(), d:decode(), type(d:decode()), #d)
e(d.decode, d)
local opts = {dict = {"k"}}; buffer.new(opts); print(opts.dict.k)

-- error messages naming the called method
print(pcall(function() local x = buffer.new(); x:put({}) end))
print(pcall(function() local x = buffer.new(); x.put(1) end))
print(pcall(function() local x = buffer.new(); x:get(-1) end))
print(pcall(function() buffer.decode("\1\1") end))
print(pcall(function() buffer.new():decode() end))
print(pcall(function() local x = buffer.new(); x:putf("%s", x) end))

-- putf writes in place: output before a __tostring call or an error stays in the buffer
local pb = buffer.new()
local po = setmetatable({}, {__tostring = function() pb:put("<in>") return "T" end})
pb:putf("a%sb%dc", po, 5); print(pb:tostring())
pb:reset(); print(pcall(pb.putf, pb, "x%dy%d", 1, "z")); print(pb:tostring())
